use xiom.io;

type Point = { x: Int; y: Int; }

fn show(p: &Point) {
  io.println(p.x.to_str());
  io.println(p.y.to_str());
}

fn move_right(p: &mut Point, dx: Int) {
  p.x = p.x + dx;
}

fn main() -> Int {
  var pt = Point{ x: 0, y: 0 };
  show(&pt);
  move_right(&mut pt, 5);
  show(&pt);
  return pt.x;
}
